INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (465, 1, 'model 값', '`<model type>` 에 **libvirt 가 아는 목록 밖의 값** 을 주면 어떻게 될까요?', '전달해요.', NULL, NULL, '[]', 'choice', '["정의가 즉시 거부된다", "virtio 로 자동 대체된다", "받아서 하이퍼바이저에 그대로 전달한다", "경고를 내고 e1000 으로 바뀐다"]', 2, '문서는 libvirt 가 호환성을 위해 type 값을 무엇이든 받아 하이퍼바이저에 넘기지만, 알려진 모델이 아니면 주소 할당 같은 추가 처리가 제대로 동작하지 않을 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 2, 'target 접두사', '직접 정하는 `target dev` 이름이 **피해야 할 접두사** 는 무엇일까요?', '예약돼 있어요.', NULL, NULL, '[]', 'choice', '["eth, ens, enp, eno", "vnet, vif, macvtap, macvlan", "br, virbr, docker, lo", "tap, tun, veth, dummy"]', 1, '문서는 직접 지정하는 이름이 libvirt 와 일부 하이퍼바이저가 예약한 vnet, vif, macvtap, macvlan 으로 시작하지 않아야 하며, 그러면 무시될 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 3, 'boot order', '인터페이스의 `<boot order="1"/>` 는 무엇을 위한 것일까요?', '네트워크 부팅이에요.', NULL, NULL, '[]', 'choice', '["네트워크 부팅 순서", "NIC 의 전송 우선순위", "NIC 의 인터럽트 번호", "NIC 의 대역폭 순위"]', 0, '문서는 하이퍼바이저가 지원하면 특정 NIC 를 네트워크 부팅에 쓰도록 정할 수 있고 order 가 부팅 순서에서 시도할 순서를 정하며, 장치별 boot 요소는 펌웨어 절의 일반 boot 요소와 함께 쓸 수 없다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 4, 'bandwidth', '`<bandwidth>` 요소의 `inbound`·`outbound` 는 무엇을 하나요?', '방향이 둘이에요.', NULL, NULL, '[]', 'choice', '["양방향을 하나의 값으로만 제한한다", "나가는 트래픽만 제한할 수 있다", "들어오는 트래픽만 제한할 수 있다", "들어오는·나가는 트래픽을 따로 제한한다"]', 3, '문서는 QoS 설정으로 들어오는 트래픽과 나가는 트래픽을 독립적으로 셰이핑할 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 5, 'vlan 지원', '인터페이스의 `<vlan>` 태그를 **쓸 수 있는 연결** 은 무엇일까요?', '투명한 태깅이에요.', NULL, NULL, '[]', 'choice', '["libvirt 가상 네트워크(network 유형)", "default 네트워크의 NAT 연결", "Open vSwitch 브리지에 붙은 bridge 유형", "ethernet 유형의 tap 연결"]', 2, '문서는 게스트에 투명한 VLAN 태깅을 지원하는 연결(Open vSwitch 브리지의 bridge 유형, SR-IOV VF 등)에서만 쓸 수 있고, libvirt 자체 가상 네트워크는 지원하지 않는다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 6, 'vlan trunk', '**단일 태그** 로 트렁킹하려면 어떻게 할까요?', '구분이 필요해요.', NULL, NULL, '[]', 'choice', '["`<tag>` 를 두 번 쓴다", "`<vlan>` 에 trunk=\\"yes\\" 를 준다", "`nativeMode` 를 tagged 로 준다", "`<port isolated=\\"yes\\"/>` 를 준다"]', 1, '문서는 여러 `<tag>` 를 쓰면 트렁킹이 되고, 태그 하나만 트렁킹하려면 최상위 `<vlan>` 에 trunk="yes" 를 더해 일반 태깅과 구분한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 7, 'port isolated', '`<port isolated="yes"/>` 인 게스트는 **isolated 가 아닌 게스트** 와 통신할 수 있을까요?', '한계가 있어요.', NULL, NULL, '[]', 'choice', '["여전히 통신할 수 있다", "통신이 완전히 차단된다", "한 방향으로만 통신한다", "관리자 승인 후에만 통신한다"]', 0, '문서는 이 설정이 isolated="yes" 인 인터페이스끼리만 통신을 막으며, 같은 브리지에 isolated 가 아닌 게스트가 있으면 격리된 게스트도 그와는 통신할 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 8, 'link state', '`<link state="down"/>` 은 게스트에게 어떻게 보일까요?', '케이블이에요.', NULL, NULL, '[]', 'choice', '["NIC 가 장치 목록에서 사라진다", "속도가 10Mbps 로 떨어진다", "트래픽이 절반으로 제한된다", "케이블이 빠진 것처럼 동작한다"]', 3, '문서는 link 요소의 state 가 up 또는 down 이며 down 이면 인터페이스가 네트워크 케이블을 뽑은 것처럼 동작하고, 지정하지 않으면 기본은 up 이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 9, 'acpi index', '`<acpi index="4"/>` 는 무엇을 위한 것일까요?', '이름 안정성이에요.', NULL, NULL, '[]', 'choice', '["NIC 의 MAC 주소를 자동 생성", "NIC 의 네트워크 부팅 순서", "PCI 주소와 무관한 안정적 NIC 이름", "NIC 의 대역폭 상한"]', 2, '문서는 systemd 같은 OS 가 ACPI 인덱스로 PCI 주소 변경에도 안정적인 네트워크 인터페이스 이름을 짓고, 값은 모든 장치에서 유일해야 하며 1 부터 16*1024-1 사이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 10, '링크 상태', '**케이블을 뽑은 것처럼** 동작하게 하는 요소입니다. 빈칸을 채우세요.', '연결 상태예요.', NULL, NULL, '[]', 'fill', '["link", "port", "vlan", "mtu"]', NULL, 'link 는 가상 링크 상태(up·down)를 정합니다. port 는 격리, vlan 은 태그, mtu 는 MTU 크기입니다.', '[0]', '<{0} state="down"/>', NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 11, '포트 격리', '같은 네트워크의 **다른 격리 인터페이스와 분리** 하는 요소입니다. 빈칸을 채우세요.', '포트예요.', NULL, NULL, '[]', 'fill', '["port", "link", "vlan", "boot"]', NULL, 'port 요소의 isolated 속성이 같은 네트워크의 다른 isolated 인터페이스와 트래픽을 분리하며 기본은 no 입니다.', '[0]', '<{0} isolated="yes"/>', NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (465, 12, '대역폭 제한', '인터페이스 대역폭을 제한하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '찾기 → 요소 → 값 → 반영이에요.', NULL, NULL, '[]', 'order', '["제한할 `<interface>` 요소를 찾는다", "`<bandwidth>` 요소를 추가한다", "`<inbound>`·`<outbound>` 에 average 같은 값을 정한다", "도메인 XML 을 정의해 반영한다"]', NULL, '문서의 Quality of service 설명을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]');
